bool canFinish(int numCourses, vector<vector<int>>& prerequisites) {
    vector<vector<int>> g(numCourses);
    vector<int> indeg(numCourses, 0);
    for (auto& p : prerequisites) {      // p = {a, b}: b לפני a
        g[p[1]].push_back(p[0]);
        ++indeg[p[0]];
    }
    queue<int> q;
    for (int i = 0; i < numCourses; ++i)
        if (indeg[i] == 0) q.push(i);
    int taken = 0;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        ++taken;
        for (int v : g[u])
            if (--indeg[v] == 0) q.push(v);
    }
    return taken == numCourses;  // מי שלא נשלף תקוע על מעגל או תלוי בו
}

int longestCycle(vector<int>& edges) {
    int n = edges.size(), ans = -1, t = 1;
    vector<int> when(n, 0);              // 0 = לא בוקר; אחרת "זמן" הביקור
    for (int s = 0; s < n; ++s) {
        if (when[s]) continue;
        int start = t, u = s;
        while (u != -1 && !when[u]) {
            when[u] = t++;
            u = edges[u];
        }
        // פגענו בצומת שבוקר בהליכה הנוכחית -> סגרנו מעגל חדש
        if (u != -1 && when[u] >= start) ans = max(ans, t - when[u]);
    }
    return ans;
}

def maximal_network_rank(n, roads):
    deg = [0] * n
    adj = set()
    for a, b in roads:
        deg[a] += 1
        deg[b] += 1
        adj.add((min(a, b), max(a, b)))
    best = 0
    for i in range(n):
        for j in range(i + 1, n):
            # כביש משותף נספר פעם אחת בלבד
            best = max(best, deg[i] + deg[j] - ((i, j) in adj))
    return best

vector<int> minEdgeReversals(int n, vector<vector<int>>& edges) {
    // c = 0: הולכים עם כיוון הקשת המקורית, c = 1: נגד הכיוון (דורש היפוך)
    vector<vector<pair<int, int>>> g(n);
    for (auto& e : edges) {
        g[e[0]].push_back({e[1], 0});
        g[e[1]].push_back({e[0], 1});
    }
    vector<int> ans(n, 0), par(n, -1), order{0};
    par[0] = 0;
    for (size_t i = 0; i < order.size(); ++i) {   // BFS מ-0: ans[0] וסדר הורה-לפני-ילד
        int u = order[i];
        for (auto [v, c] : g[u])
            if (par[v] == -1) { par[v] = u; ans[0] += c; order.push_back(v); }
    }
    for (int u : order)                             // rerooting: רק הקשת u-v משנה כיוון
        for (auto [v, c] : g[u])
            if (v != par[u]) ans[v] = ans[u] + (c == 0 ? 1 : -1);
    return ans;
}

def accounts_merge(accounts):
    parent = {}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]   # path halving
            x = parent[x]
        return x

    owner = {}
    for acc in accounts:
        name, first = acc[0], acc[1]
        for e in acc[1:]:
            if e not in parent:
                parent[e] = e
            owner[e] = name
            parent[find(e)] = find(first)   # כל המיילים של חשבון באותה קבוצה
    groups = {}
    for e in parent:
        groups.setdefault(find(e), []).append(e)
    return [[owner[r]] + sorted(es) for r, es in groups.items()]

int minReorder(int n, vector<vector<int>>& connections) {
    // c = 1: הקשת המקורית מצביעה הרחק מ-0, צריך להפוך אותה
    vector<vector<pair<int, int>>> g(n);
    for (auto& e : connections) {
        g[e[0]].push_back({e[1], 1});
        g[e[1]].push_back({e[0], 0});
    }
    vector<bool> seen(n, false);
    vector<int> st{0};
    seen[0] = true;
    int ans = 0;
    while (!st.empty()) {
        int u = st.back(); st.pop_back();
        for (auto [v, c] : g[u])
            if (!seen[v]) { seen[v] = true; ans += c; st.push_back(v); }
    }
    return ans;
}

