struct DSU {
    vector<int> p, r;
    DSU(int n) : p(n), r(n, 0) { iota(p.begin(), p.end(), 0); }
    int find(int x) { return p[x] == x ? x : p[x] = find(p[x]); }
    void unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (r[a] < r[b]) swap(a, b);
        p[b] = a;
        if (r[a] == r[b]) ++r[a];
    }
};
bool possibleBipartition(int n, vector<vector<int>>& dislikes) {
    vector<vector<int>> g(n + 1);
    for (auto& d : dislikes) { g[d[0]].push_back(d[1]); g[d[1]].push_back(d[0]); }
    DSU dsu(n + 1);
    for (int u = 1; u <= n; ++u)
        for (int v : g[u]) {
            if (dsu.find(u) == dsu.find(v)) return false;  // חייבים להיות בצדדים שונים
            dsu.unite(g[u][0], v);   // כל מי ש-u לא סובל נמצא באותו צד (הצד שמול u)
        }
    return true;
}

def is_bipartite(graph):
    n = len(graph)
    color = [-1] * n
    for s in range(n):               # כל רכיב קשירות בנפרד
        if color[s] != -1:
            continue
        color[s] = 0
        stack = [s]
        while stack:
            u = stack.pop()
            for v in graph[u]:
                if color[v] == -1:
                    color[v] = 1 - color[u]
                    stack.append(v)
                elif color[v] == color[u]:
                    return False     # קשת בין שני צמתים באותו צבע: מעגל אי-זוגי
    return True

int findCircleNum(vector<vector<int>>& isConnected) {
    int n = isConnected.size(), comps = n;
    vector<int> p(n);
    iota(p.begin(), p.end(), 0);
    function<int(int)> find = [&](int x) {
        return p[x] == x ? x : p[x] = find(p[x]);
    };
    for (int i = 0; i < n; ++i)
        for (int j = i + 1; j < n; ++j)          // המטריצה סימטרית: חצי מספיק
            if (isConnected[i][j]) {
                int a = find(i), b = find(j);
                if (a != b) { p[a] = b; --comps; }  // כל איחוד מוצלח מוריד רכיב אחד
            }
    return comps;
}

int findCelebrity(int n, function<bool(int, int)> knows) {
    int c = 0;
    for (int i = 1; i < n; ++i)
        if (knows(c, i)) c = i;   // c מכיר מישהו -> c נפסל, i נשאר מועמד
                                  // אחרת: c לא מכיר את i -> i נפסל
    for (int i = 0; i < n; ++i) {
        if (i == c) continue;
        if (knows(c, i) || !knows(i, c)) return -1;  // אימות: ייתכן שאין סלבריטי
    }
    return c;
}

vector<int> smallestTopoOrder(int n, vector<vector<int>>& edges) {
    vector<vector<int>> g(n);
    vector<int> indeg(n, 0);
    for (auto& e : edges) { g[e[0]].push_back(e[1]); ++indeg[e[1]]; }
    priority_queue<int, vector<int>, greater<int>> pq;   // min-heap במקום queue
    for (int i = 0; i < n; ++i)
        if (indeg[i] == 0) pq.push(i);
    vector<int> order;
    while (!pq.empty()) {
        int u = pq.top(); pq.pop();
        order.push_back(u);
        for (int v : g[u])
            if (--indeg[v] == 0) pq.push(v);
    }
    if ((int)order.size() != n) return {};   // יש מעגל
    return order;
}

vector<int> findCycle(int n, vector<vector<int>>& edges) {
    vector<vector<int>> g(n);
    for (auto& e : edges) g[e[0]].push_back(e[1]);
    vector<int> color(n, 0), par(n, -1);   // 0 white, 1 gray (במסלול הנוכחי), 2 black
    int cs = -1, ce = -1;                  // back edge: ce -> cs
    function<bool(int)> dfs = [&](int u) {
        color[u] = 1;
        for (int v : g[u]) {
            if (color[v] == 0) {
                par[v] = u;
                if (dfs(v)) return true;
            } else if (color[v] == 1) {    // gray = אב קדמון במסלול הנוכחי
                cs = v; ce = u;
                return true;
            }                              // black: כבר נסגר, לא מעיד על מעגל
        }
        color[u] = 2;
        return false;
    };
    for (int i = 0; i < n && cs == -1; ++i)
        if (color[i] == 0) dfs(i);
    if (cs == -1) return {};
    vector<int> cyc;
    for (int x = ce; x != cs; x = par[x]) cyc.push_back(x);
    cyc.push_back(cs);
    reverse(cyc.begin(), cyc.end());       // cs -> ... -> ce, ומ-ce קשת חזרה ל-cs
    return cyc;
}

import heapq

def shortest_path(n, edges, s, t):
    g = [[] for _ in range(n)]
    for u, v, w in edges:
        g[u].append((v, w))
    INF = float('inf')
    dist = [INF] * n
    parent = [-1] * n
    dist[s] = 0
    pq = [(0, s)]
    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue                 # רשומה ישנה
        if u == t:
            break                    # t נשלף: המרחק שלו סופי
        for v, w in g[u]:
            if d + w < dist[v]:
                dist[v] = d + w
                parent[v] = u        # זוכרים מאיפה הגענו
                heapq.heappush(pq, (dist[v], v))
    if dist[t] == INF:
        return -1, []
    path = []
    x = t
    while x != -1:
        path.append(x)
        x = parent[x]
    return dist[t], path[::-1]

vector<int> sccIds(int n, vector<vector<int>>& edges) {
    vector<vector<int>> g(n), gt(n);
    for (auto& e : edges) { g[e[0]].push_back(e[1]); gt[e[1]].push_back(e[0]); }
    // מעבר 1: DFS איטרטיבי על G, צומת נכנס ל-order כשהוא מסתיים
    vector<int> order;
    vector<char> seen(n, 0);
    for (int s = 0; s < n; ++s) {
        if (seen[s]) continue;
        vector<pair<int, size_t>> st{{s, 0}};
        seen[s] = 1;
        while (!st.empty()) {
            int u = st.back().first;
            size_t i = st.back().second;
            if (i < g[u].size()) {
                st.back().second++;          // לפני push_back (שעלול להזיז את הזיכרון)
                int v = g[u][i];
                if (!seen[v]) { seen[v] = 1; st.push_back({v, 0}); }
            } else {
                order.push_back(u);
                st.pop_back();
            }
        }
    }
    // מעבר 2: על G^T בסדר זמני סיום יורד; כל עץ הוא SCC אחד
    vector<int> comp(n, -1);
    int cnt = 0;
    for (int k = n - 1; k >= 0; --k) {
        int s = order[k];
        if (comp[s] != -1) continue;
        vector<int> st{s};
        comp[s] = cnt;
        while (!st.empty()) {
            int u = st.back(); st.pop_back();
            for (int v : gt[u])
                if (comp[v] == -1) { comp[v] = cnt; st.push_back(v); }
        }
        ++cnt;
    }
    return comp;   // מספר ה-SCC הוא cnt = max(comp) + 1
}

vector<long long> shortestWithNegCycles(int n, vector<vector<int>>& edges, int src) {
    const long long INF = LLONG_MAX, NINF = LLONG_MIN;
    vector<long long> d(n, INF);
    d[src] = 0;
    for (int r = 0; r < n - 1; ++r)
        for (auto& e : edges)
            if (d[e[0]] != INF && d[e[0]] + e[2] < d[e[1]]) d[e[1]] = d[e[0]] + e[2];
    // מי שעדיין משתפר בסבב ה-n מושפע ממעגל שלילי
    vector<vector<int>> g(n);
    for (auto& e : edges) g[e[0]].push_back(e[1]);
    queue<int> q;
    for (auto& e : edges) {
        int u = e[0], v = e[1];
        if (d[u] != INF && d[u] != NINF && d[v] != NINF && d[u] + e[2] < d[v]) {
            d[v] = NINF;
            q.push(v);
        }
    }
    while (!q.empty()) {                  // כל מה שישיג מהם גם -inf
        int u = q.front(); q.pop();
        for (int v : g[u])
            if (d[v] != NINF) { d[v] = NINF; q.push(v); }
    }
    return d;   // INF = לא ישיג, NINF = אין מסלול קצר ביותר
}
